import { describe, it } from "vitest";

describe("claim office quote", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword for newcomer -> 100 base + 10 first insurance + 5 fee = 115 G");
  it.todo("plain amulet for newcomer -> 60 base + 6 first insurance + 5 fee = 71 G");
  it.todo("plain staff for newcomer -> 80 base + 8 first insurance + 5 fee = 93 G");
  it.todo("plain potion for newcomer -> 40 base + 4 first insurance + 5 fee = 49 G");
  it.todo("2 runes -> 50 G base premium -> 55 + 5 = 60 G");
  it.todo("1 moonstone -> 25 G base premium -> 27.5 + 5 = 32.5 -> 33 G (rounded up)");
  it.todo("3 runes -> 60 G base premium (block) -> 66 + 5 = 71 G");
  it.todo("4 runes -> 100 G base premium (no block) -> 110 + 5 = 115 G");
  it.todo("7 runes -> 175 G base premium -> 192.5 + 5 = 197.5 -> 198 G");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (different types, no block) -> 82.5 + 5 -> 88 G");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two blocks) -> 132 + 5 = 137 G");
  it.todo("newcomer with a cursed sword (steel, enchantment 3) -> 165 G");
  it.todo("cursed sword + plain amulet -> 160 base + 50 curse on sword only + 16 first insurance + 5 fee = 231 G");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> 115 G");
  it.todo("sword with exactly enchantment 5 -> 30 % surcharge -> 100 + 30 + 10 + 5 = 145 G");
  it.todo("cursed sword with enchantment 5 -> both surcharges -> 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("customer with exactly 2 years -> loyalty discount -> 100 - 20 + 10 + 5 = 95 G");
  it.todo("customer with 1 year -> no loyalty discount -> 115 G");
  it.todo("second quote in the scenario -> 15 % follow-up discount -> 100 + 10 - 15 + 5 = 100 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 -> 160 G");
  it.todo("cursed sword + 2 runes on second quote -> 197.5 G -> 198 G (rounded up in MHPCO's favor)");
  it.todo("quote with unknown item type broomstick -> runScenario throws an Error");
});

describe("claim office claim", () => {
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400, remaining cap 1600");
  it.todo("rune damage 200 -> payout 100, remaining cap 400");
  it.todo("amulet schema example, damage 200 -> payout 100, remaining cap 1100");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400 (50 % then deductible)");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> payout 400 (50 % rule wins)");
  it.todo("dragon-material sword enchantment 5, damage 800 -> payout 700 (full reimbursement)");
  it.todo("dragon-material sword exactly enchantment 8, damage 1000 -> payout 400");
  it.todo("steel sword enchantment 9, damage 901 -> 350.5 -> payout 350 (rounded down)");
  it.todo("dragon attack damages sword 500 and amulet 300 -> payout 600 (deductible per damaged item)");
  it.todo("damage below deductible, sword damage 50 -> payout 0 (payout never negative)");
  it.todo("two swords insured -> cap 4000; both damaged 1000 each -> payout 1800, remaining cap 2200");
  it.todo("two swords, first plain second enchantment 9 -> damages consume items in order -> 900 + 400 = 1300");
  it.todo("sword + amulet -> cap 3200; damage 2000 + 1500 -> payout 3200 capped, remaining cap 0");
  it.todo("cursed sword -> cap 2000 based on unmodified insurance value; damage 2500 -> payout 2000, remaining 0");
  it.todo("sword + 3 runes block -> insurance sum 1750, cap 3500; sword damage 1100 -> payout 1000, remaining 2500");
  it.todo("sword, two successive claims of 1500 -> 1400 remaining 600, then 600 remaining 0");
  it.todo("claims on separate policies keep separate caps");
  it.todo("two sword damages with only one sword insured -> runScenario throws an Error");
  it.todo("amulet damaged when only a sword is insured -> runScenario throws an Error");
  it.todo("damage for unknown item type broomstick -> runScenario throws an Error");
  it.todo("damage with amount -200 -> runScenario throws an Error");
});

describe("claim-office CLI", () => {
  it.todo("reads the schema example scenario from stdin and writes results JSON to stdout with exit code 0");
  it.todo("unknown quote item type -> non-zero exit, error on stderr, nothing on stdout");
  it.todo("claim damage for an uninsured item -> non-zero exit, error on stderr");
  it.todo("negative damage amount -> non-zero exit, error on stderr");
  it.todo("more damages of a type than insured -> non-zero exit, whole claim rejected");
});

