input.command:
cat > src/claim-office.ts <<'EOF'
export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface StepResult {
  premium?: number;
  payout?: number;
  remainingCap?: number;
}

const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE = 0.1;

function quote(step: QuoteStep): number {
  const basePremium = step.items.length * SWORD_BASE_PREMIUM;
  return Math.ceil(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
}
EOF
pnpm test 2>&1 | grep -E "AssertionError|Tests |Test Files"; npx tsc --noEmit && echo TSC OK

